package com.bank.orgchart;

import java.util.logging.Logger;

public class LevelOrderDemo {
    private static final Logger log = Logger.getLogger(LevelOrderDemo.class.getName());

    public static void main(String[] args) {
        // Tree:        1
        //            /   \
        //           2     3
        //          / \     \
        //         4   5     6
        ApprovalNode root = new ApprovalNode(1);
        root.left = new ApprovalNode(2);
        root.right = new ApprovalNode(3);
        root.left.left = new ApprovalNode(4);
        root.left.right = new ApprovalNode(5);
        root.right.right = new ApprovalNode(6);

        log.info("Level order approval chart: " + new OrgChartService().levelOrder(root));
    }
}
